from __future__ import annotations

import time
from typing import Any


class TtlCache:
    def __init__(self, ttl_seconds: float = 600.0) -> None:
        self.ttl_seconds = ttl_seconds
        self._store: dict[str, tuple[float, Any]] = {}

    def get(self, key: str) -> Any | None:
        item = self._store.get(key)
        if not item:
            return None
        expires_at, value = item
        if time.time() > expires_at:
            self._store.pop(key, None)
            return None
        return value

    def set(self, key: str, value: Any) -> None:
        self._store[key] = (time.time() + self.ttl_seconds, value)

from __future__ import annotations

from typing import Any

import httpx

from lib.cache import TtlCache
from lib.geo import haversine_km

USER_AGENT = "LocalityIdeaAssistant/1.0 (educational MVP; contact: local-dev)"
NOMINATIM = "https://nominatim.openstreetmap.org"
OVERPASS_URLS = (
    "https://overpass-api.de/api/interpreter",
    "https://overpass.kumi.systems/api/interpreter",
)

_cache = TtlCache(ttl_seconds=900)


def _client() -> httpx.Client:
    return httpx.Client(
        timeout=httpx.Timeout(20.0, connect=8.0),
        headers={"User-Agent": USER_AGENT, "Accept": "application/json"},
        follow_redirects=True,
    )


def reverse_geocode(lat: float, lon: float) -> dict[str, Any]:
    key = f"rev:{round(lat, 4)}:{round(lon, 4)}"
    cached = _cache.get(key)
    if cached:
        return cached
    with _client() as client:
        response = client.get(
            f"{NOMINATIM}/reverse",
            params={"lat": lat, "lon": lon, "format": "jsonv2"},
        )
        response.raise_for_status()
        data = response.json()
    address = data.get("address") or {}
    result = {
        "lat": lat,
        "lon": lon,
        "label": data.get("display_name") or f"{lat:.4f}, {lon:.4f}",
        "country": address.get("country") or "",
        "city": address.get("city")
        or address.get("town")
        or address.get("village")
        or address.get("municipality")
        or "",
        "region": address.get("state") or address.get("county") or "",
    }
    _cache.set(key, result)
    return result


def geocode_query(query: str) -> dict[str, Any]:
    key = f"fwd:{query.strip().lower()}"
    cached = _cache.get(key)
    if cached:
        return cached
    with _client() as client:
        response = client.get(
            f"{NOMINATIM}/search",
            params={"q": query, "format": "jsonv2", "limit": 1},
        )
        response.raise_for_status()
        rows = response.json()
    if not rows:
        raise ValueError(f"No place found for {query!r}")
    row = rows[0]
    lat, lon = float(row["lat"]), float(row["lon"])
    result = reverse_geocode(lat, lon)
    result["label"] = row.get("display_name") or result["label"]
    _cache.set(key, result)
    return result


def _resource_type(tags: dict[str, str]) -> str:
    leisure = tags.get("leisure", "")
    amenity = tags.get("amenity", "")
    shop = tags.get("shop", "")
    if leisure == "hackerspace" or amenity in {"makerspace", "hackerspace"}:
        return "makerspace"
    if shop == "electronics":
        return "electronics"
    if shop == "hardware":
        return "hardware"
    return shop or amenity or leisure or "other"


def nearby_resources(lat: float, lon: float, radius_m: int = 15000) -> tuple[list[dict[str, Any]], str | None]:
    key = f"osm:{round(lat, 3)}:{round(lon, 3)}:{radius_m}"
    cached = _cache.get(key)
    if cached is not None:
        return cached

    query = f"""
    [out:json][timeout:18];
    (
      nwr["leisure"="hackerspace"](around:{radius_m},{lat},{lon});
      nwr["amenity"="hackerspace"](around:{radius_m},{lat},{lon});
      nwr["amenity"="makerspace"](around:{radius_m},{lat},{lon});
      nwr["shop"="electronics"](around:{radius_m},{lat},{lon});
      nwr["shop"="hardware"](around:{radius_m},{lat},{lon});
    );
    out center 40;
    """
    note: str | None = None
    elements: list[dict[str, Any]] = []
    last_error: Exception | None = None
    with _client() as client:
        for url in OVERPASS_URLS:
            try:
                response = client.post(url, content=query.encode("utf-8"))
                response.raise_for_status()
                payload = response.json()
                elements = payload.get("elements") or []
                last_error = None
                break
            except Exception as exc:  # noqa: BLE001 — fallback to next mirror / empty list
                last_error = exc
                continue
    if last_error and not elements:
        note = "Nearby OSM resources unavailable; ideas will use place name only."

    resources: list[dict[str, Any]] = []
    seen: set[str] = set()
    for el in elements:
        tags = el.get("tags") or {}
        name = tags.get("name")
        if not name:
            continue
        elat = el.get("lat") or (el.get("center") or {}).get("lat")
        elon = el.get("lon") or (el.get("center") or {}).get("lon")
        if elat is None or elon is None:
            continue
        ident = f"{name}|{round(float(elat), 4)}|{round(float(elon), 4)}"
        if ident in seen:
            continue
        seen.add(ident)
        resources.append(
            {
                "name": name,
                "type": _resource_type(tags),
                "lat": float(elat),
                "lon": float(elon),
                "distanceKm": round(haversine_km(lat, lon, float(elat), float(elon)), 2),
            }
        )
    resources.sort(key=lambda r: r["distanceKm"])
    result = (resources[:25], note)
    _cache.set(key, result)
    return result


def resolve_locality(query: str | None, lat: float | None, lon: float | None) -> dict[str, Any]:
    if lat is not None and lon is not None:
        place = reverse_geocode(lat, lon)
    elif query:
        place = geocode_query(query)
    else:
        raise ValueError("Provide a place name or coordinates.")

    resources, note = nearby_resources(place["lat"], place["lon"])
    return {**place, "resources": resources, "resourcesNote": note}

from __future__ import annotations

import json
import os
from pathlib import Path

from dotenv import load_dotenv
from fastapi import FastAPI, HTTPException
from fastapi.responses import FileResponse, StreamingResponse
from fastapi.staticfiles import StaticFiles
from pydantic import BaseModel, Field

from lib.llm import generate_ideas, stream_chat
from lib.locality import resolve_locality

load_dotenv(Path(__file__).parent / ".env")
load_dotenv(Path(__file__).parent / ".env.local")

ROOT = Path(__file__).parent
STATIC = ROOT / "static"

app = FastAPI(title="Locality Idea Assistant")
app.mount("/static", StaticFiles(directory=STATIC), name="static")


class LocalityRequest(BaseModel):
    query: str | None = None
    lat: float | None = None
    lon: float | None = None


class IdeasRequest(BaseModel):
    locality: dict = Field(default_factory=dict)


class ChatMessage(BaseModel):
    role: str
    content: str


class ChatRequest(BaseModel):
    messages: list[ChatMessage]
    idea: dict
    locality: dict


@app.get("/")
def index() -> FileResponse:
    return FileResponse(STATIC / "index.html")


@app.post("/api/locality")
def api_locality(body: LocalityRequest) -> dict:
    try:
        return resolve_locality(body.query, body.lat, body.lon)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    except Exception as exc:  # noqa: BLE001
        raise HTTPException(status_code=502, detail=f"Geocoding failed: {exc}") from exc


@app.post("/api/ideas")
def api_ideas(body: IdeasRequest) -> dict:
    locality = body.locality
    if not locality.get("label") and not (locality.get("lat") and locality.get("lon")):
        raise HTTPException(status_code=400, detail="locality is required")
    try:
        ideas = generate_ideas(locality)
    except Exception as exc:  # noqa: BLE001
        raise HTTPException(status_code=502, detail=f"Idea generation failed: {exc}") from exc
    return {"ideas": ideas, "mock": os.getenv("MOCK_LLM", "")}


@app.post("/api/chat")
def api_chat(body: ChatRequest) -> StreamingResponse:
    messages = [m.model_dump() for m in body.messages if m.role in {"user", "assistant"}]
    if not body.idea.get("title"):
        raise HTTPException(status_code=400, detail="idea is required")

    def event_stream():
        try:
            for token in stream_chat(messages, body.idea, body.locality):
                yield f"data: {json.dumps({'text': token})}\n\n"
            yield "data: [DONE]\n\n"
        except Exception as exc:  # noqa: BLE001
            yield f"data: {json.dumps({'error': str(exc)})}\n\n"

    return StreamingResponse(event_stream(), media_type="text/event-stream")


if __name__ == "__main__":
    import uvicorn

    uvicorn.run("server:app", host="127.0.0.1", port=8000, reload=True)

:root {
  --bg: #0f1419;
  --panel: #1a222c;
  --line: #2c3846;
  --text: #e8eef4;
  --muted: #93a4b8;
  --accent: #3d9cf0;
  --accent-2: #4ade80;
  --warn: #fbbf24;
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; }
body {
  font-family: "Segoe UI", system-ui, sans-serif;
  background: radial-gradient(1200px 600px at 10% -10%, #1d3a5c 0%, var(--bg) 50%);
  color: var(--text);
}

.app { max-width: 1100px; margin: 0 auto; padding: 24px 16px 48px; }
header h1 { margin: 0 0 6px; font-size: 1.6rem; }
header p { margin: 0 0 20px; color: var(--muted); }

.row { display: flex; gap: 8px; flex-wrap: wrap; }
input, select, textarea, button {
  font: inherit;
  border-radius: 10px;
  border: 1px solid var(--line);
  background: var(--panel);
  color: var(--text);
  padding: 10px 12px;
}
input { flex: 1; min-width: 180px; }
button { cursor: pointer; background: var(--accent); border: none; color: #041018; font-weight: 600; }
button.secondary { background: transparent; color: var(--text); border: 1px solid var(--line); }
button:disabled { opacity: 0.55; cursor: not-allowed; }

.status { color: var(--muted); min-height: 1.3em; margin: 10px 0; font-size: 0.92rem; }
.filters { display: flex; gap: 8px; margin: 12px 0; }
.filters button[aria-pressed="true"] { background: var(--accent-2); color: #052e16; }

.grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 12px; }
.card {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 14px;
  cursor: pointer;
  text-align: left;
}
.card:hover { border-color: var(--accent); }
.badge {
  display: inline-block;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--warn);
  margin-bottom: 6px;
}

.split { display: grid; grid-template-columns: 1fr 1.2fr; gap: 16px; }
@media (max-width: 860px) { .split { grid-template-columns: 1fr; } }

.panel { background: var(--panel); border: 1px solid var(--line); border-radius: 14px; padding: 14px; }
.resources { font-size: 0.88rem; color: var(--muted); }
.resources li { margin: 4px 0; }

.chat { display: flex; flex-direction: column; height: min(70vh, 720px); }
.threads { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 8px; }
.messages { flex: 1; overflow: auto; display: flex; flex-direction: column; gap: 10px; padding-right: 4px; }
.bubble { padding: 10px 12px; border-radius: 12px; line-height: 1.45; }
.bubble.user { background: #243044; align-self: flex-end; max-width: 90%; }
.bubble.assistant { background: #12181f; border: 1px solid var(--line); }
.bubble.assistant pre { overflow: auto; background: #0b0f14; padding: 8px; border-radius: 8px; }
.composer { display: flex; gap: 8px; margin-top: 10px; }
.composer textarea { flex: 1; min-height: 52px; resize: vertical; }

.hidden { display: none; }
.back { margin-bottom: 12px; }

const LOCATION_KEY = "lia.location";
const IDEAS_KEY = "lia.ideas";
const THREADS_KEY = "lia.threads";

const els = {
  place: document.getElementById("place"),
  useLocation: document.getElementById("use-location"),
  search: document.getElementById("search"),
  status: document.getElementById("status"),
  localitySummary: document.getElementById("locality-summary"),
  ideas: document.getElementById("ideas"),
  filters: document.getElementById("filters"),
  searchView: document.getElementById("search-view"),
  ideaView: document.getElementById("idea-view"),
  back: document.getElementById("back"),
  ideaKind: document.getElementById("idea-kind"),
  ideaTitle: document.getElementById("idea-title"),
  ideaProblem: document.getElementById("idea-problem"),
  ideaWhy: document.getElementById("idea-why"),
  ideaSw: document.getElementById("idea-sw"),
  ideaHw: document.getElementById("idea-hw"),
  ideaResources: document.getElementById("idea-resources"),
  messages: document.getElementById("messages"),
  prompt: document.getElementById("prompt"),
  send: document.getElementById("send"),
  stop: document.getElementById("stop"),
  newChat: document.getElementById("new-chat"),
  threadList: document.getElementById("thread-list"),
};

let locality = null;
let ideas = [];
let filterKind = "all";
let activeIdea = null;
let activeThreadId = null;
let abortController = null;

function loadJson(key, fallback) {
  try {
    return JSON.parse(localStorage.getItem(key) || "") ?? fallback;
  } catch {
    return fallback;
  }
}

function saveJson(key, value) {
  localStorage.setItem(key, JSON.stringify(value));
}

function setStatus(text) {
  els.status.textContent = text;
}

function renderLocality() {
  if (!locality) {
    els.localitySummary.textContent = "";
    return;
  }
  const note = locality.resourcesNote ? ` ${locality.resourcesNote}` : "";
  const res = (locality.resources || [])
    .slice(0, 8)
    .map((r) => `${r.name} (${r.type}, ${r.distanceKm} km)`)
    .join(" · ");
  els.localitySummary.textContent = `${locality.label}.${note}${res ? " Nearby: " + res : ""}`;
}

function renderIdeas() {
  els.ideas.innerHTML = "";
  const list = ideas.filter((i) => filterKind === "all" || i.kind === filterKind);
  for (const idea of list) {
    const btn = document.createElement("button");
    btn.className = "card";
    btn.type = "button";
    btn.innerHTML = `<div class="badge">${idea.kind} · ${idea.difficulty || ""}</div>
      <strong>${idea.title}</strong>
      <p>${idea.localProblem || ""}</p>`;
    btn.addEventListener("click", () => openIdea(idea));
    els.ideas.appendChild(btn);
  }
}

function allThreads() {
  return loadJson(THREADS_KEY, []);
}

function saveThreads(threads) {
  saveJson(THREADS_KEY, threads);
}

function threadsForIdea(ideaId) {
  return allThreads().filter((t) => t.ideaId === ideaId);
}

function uid() {
  return crypto.randomUUID ? crypto.randomUUID() : String(Date.now());
}

function renderThreadSelect() {
  const threads = threadsForIdea(activeIdea.id);
  els.threadList.innerHTML = "";
  for (const t of threads) {
    const opt = document.createElement("option");
    opt.value = t.id;
    opt.textContent = t.title || "Chat";
    if (t.id === activeThreadId) opt.selected = true;
    els.threadList.appendChild(opt);
  }
}

function renderMessages(messages) {
  els.messages.innerHTML = "";
  for (const m of messages) {
    const div = document.createElement("div");
    div.className = `bubble ${m.role}`;
    if (m.role === "assistant" && window.marked) {
      div.innerHTML = window.marked.parse(m.content || "");
    } else {
      div.textContent = m.content || "";
    }
    els.messages.appendChild(div);
  }
  els.messages.scrollTop = els.messages.scrollHeight;
}

function getActiveThread() {
  return allThreads().find((t) => t.id === activeThreadId);
}

function upsertThread(thread) {
  const threads = allThreads().filter((t) => t.id !== thread.id);
  threads.unshift(thread);
  saveThreads(threads);
}

function openIdea(idea) {
  activeIdea = idea;
  els.searchView.classList.add("hidden");
  els.ideaView.classList.remove("hidden");
  els.ideaKind.textContent = `${idea.kind} · ${idea.difficulty || ""}`;
  els.ideaTitle.textContent = idea.title;
  els.ideaProblem.textContent = idea.localProblem || "";
  els.ideaWhy.textContent = idea.whyHere || "";
  els.ideaSw.textContent = idea.softwareSketch || "";
  els.ideaHw.textContent = idea.hardwareSketch || "";
  els.ideaResources.innerHTML = "";
  const names = idea.suggestedResources?.length
    ? idea.suggestedResources
    : (locality?.resources || []).map((r) => `${r.name} (${r.type})`);
  if (!names.length) {
    const li = document.createElement("li");
    li.textContent = locality?.resourcesNote || "No mapped shops yet — source parts online or by city search.";
    els.ideaResources.appendChild(li);
  } else {
    for (const name of names) {
      const li = document.createElement("li");
      li.textContent = name;
      els.ideaResources.appendChild(li);
    }
  }

  let threads = threadsForIdea(idea.id);
  if (!threads.length) {
    const thread = {
      id: uid(),
      ideaId: idea.id,
      title: "Build plan",
      messages: [],
      createdAt: Date.now(),
    };
    upsertThread(thread);
    activeThreadId = thread.id;
    renderThreadSelect();
    renderMessages([]);
    void sendChat("Write the full software and hardware build plan for this idea.", true);
    return;
  }
  activeThreadId = threads[0].id;
  renderThreadSelect();
  renderMessages(getActiveThread().messages);
}

async function resolveLocality(payload) {
  const res = await fetch("/api/locality", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.detail || "Locality lookup failed");
  locality = data;
  saveJson(LOCATION_KEY, locality);
  renderLocality();
  return data;
}

async function searchIdeas() {
  if (!locality) throw new Error("Set a location first");
  const cached = loadJson(IDEAS_KEY, null);
  if (cached && cached.label === locality.label && Array.isArray(cached.ideas)) {
    ideas = cached.ideas;
    renderIdeas();
    setStatus("Loaded last idea search for this place. Search again to refresh.");
    return;
  }
  setStatus("Generating ideas…");
  const res = await fetch("/api/ideas", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ locality }),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.detail || "Idea search failed");
  ideas = data.ideas || [];
  saveJson(IDEAS_KEY, { label: locality.label, ideas });
  renderIdeas();
  setStatus(`${ideas.length} ideas for ${locality.city || locality.label}`);
}

els.useLocation.addEventListener("click", () => {
  if (!navigator.geolocation) {
    setStatus("Geolocation is not available in this browser.");
    return;
  }
  setStatus("Requesting location…");
  navigator.geolocation.getCurrentPosition(
    async (pos) => {
      try {
        await resolveLocality({ lat: pos.coords.latitude, lon: pos.coords.longitude });
        await searchIdeas();
      } catch (err) {
        setStatus(err.message);
      }
    },
    () => setStatus("Location permission denied. Type a city instead."),
  );
});

els.search.addEventListener("click", async () => {
  try {
    setStatus("Looking up place…");
    await resolveLocality({ query: els.place.value.trim() });
    saveJson(IDEAS_KEY, null);
    await searchIdeas();
  } catch (err) {
    setStatus(err.message);
  }
});

els.filters.addEventListener("click", (event) => {
  const btn = event.target.closest("button[data-kind]");
  if (!btn) return;
  filterKind = btn.dataset.kind;
  for (const b of els.filters.querySelectorAll("button")) {
    b.setAttribute("aria-pressed", String(b === btn));
  }
  renderIdeas();
});

els.back.addEventListener("click", () => {
  if (abortController) abortController.abort();
  els.ideaView.classList.add("hidden");
  els.searchView.classList.remove("hidden");
});

els.newChat.addEventListener("click", () => {
  if (!activeIdea) return;
  const thread = {
    id: uid(),
    ideaId: activeIdea.id,
    title: "New chat",
    messages: [],
    createdAt: Date.now(),
  };
  upsertThread(thread);
  activeThreadId = thread.id;
  renderThreadSelect();
  renderMessages([]);
});

els.threadList.addEventListener("change", () => {
  activeThreadId = els.threadList.value;
  renderMessages(getActiveThread()?.messages || []);
});

els.stop.addEventListener("click", () => {
  if (abortController) abortController.abort();
});

els.send.addEventListener("click", () => {
  const text = els.prompt.value.trim();
  if (!text) return;
  els.prompt.value = "";
  void sendChat(text, false);
});

els.prompt.addEventListener("keydown", (event) => {
  if (event.key === "Enter" && !event.shiftKey) {
    event.preventDefault();
    els.send.click();
  }
});

async function sendChat(userText, isKickoff) {
  const thread = getActiveThread();
  if (!thread) return;
  thread.messages.push({ role: "user", content: userText });
  const assistant = { role: "assistant", content: "" };
  thread.messages.push(assistant);
  upsertThread(thread);
  renderMessages(thread.messages);

  abortController = new AbortController();
  els.send.disabled = true;
  try {
    const res = await fetch("/api/chat", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        messages: thread.messages.filter((m) => m.content),
        idea: activeIdea,
        locality,
      }),
      signal: abortController.signal,
    });
    if (!res.ok || !res.body) {
      const err = await res.json().catch(() => ({}));
      throw new Error(err.detail || "Chat failed");
    }
    const reader = res.body.getReader();
    const decoder = new TextDecoder();
    let buffer = "";
    while (true) {
      const { value, done } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      const parts = buffer.split("\n\n");
      buffer = parts.pop() || "";
      for (const part of parts) {
        const line = part.split("\n").find((l) => l.startsWith("data:"));
        if (!line) continue;
        const data = line.slice(5).trim();
        if (data === "[DONE]") continue;
        const payload = JSON.parse(data);
        if (payload.error) throw new Error(payload.error);
        assistant.content += payload.text || "";
        renderMessages(thread.messages);
      }
    }
    if (isKickoff) thread.title = "Build plan";
    else if (thread.title === "New chat") thread.title = userText.slice(0, 40);
    upsertThread(thread);
    renderThreadSelect();
  } catch (err) {
    if (err.name !== "AbortError") {
      assistant.content += `\n\n(${err.message})`;
      upsertThread(thread);
      renderMessages(thread.messages);
    }
  } finally {
    els.send.disabled = false;
    abortController = null;
  }
}

const savedLoc = loadJson(LOCATION_KEY, null);
if (savedLoc?.label) {
  locality = savedLoc;
  els.place.value = savedLoc.city || savedLoc.label;
  renderLocality();
  const cached = loadJson(IDEAS_KEY, null);
  if (cached?.ideas) {
    ideas = cached.ideas;
    renderIdeas();
  }
}
